import modal

image = modal.Image.debian_slim().pip_install("torch", "transformers", "fastapi[standard]")
app = modal.App("modal-sentiment-demo")

@app.cls(image=image, cpu=1.0, timeout=60)
class SentimentModel:
    @modal.enter()
    def load_model(self):  # runs once per container, not on every request
        from transformers import pipeline
        self.classifier = pipeline(
            "sentiment-analysis",
            model="distilbert/distilbert-base-uncased-finetuned-sst-2-english",
        )

    @modal.fastapi_endpoint(method="POST")
    def predict(self, payload: dict):  # your frontend calls this URL
        result = self.classifier(payload["text"])[0]
        return {"label": result["label"], "confidence": round(result["score"], 4)}

from langsmith import Client

client = Client()  # reads LANGSMITH_API_KEY from the environment
dataset = client.create_dataset("python-basics")
client.create_examples(dataset_id=dataset.id, examples=[
    {"inputs": {"question": "What does break do?"},
     "outputs": {"concepts": [["break"], ["stop", "terminate", "end"], ["loop"]]}},
])

def has_concepts(outputs, reference_outputs):
    answer = outputs["answer"].lower()
    ok = all(any(w in answer for w in group) for group in reference_outputs["concepts"])
    return {"key": "concepts", "score": int(ok)}

for name, rag in [("rag-v1", rag_v1), ("rag-v2", rag_v2)]:
    client.evaluate(rag, data="python-basics", evaluators=[has_concepts], experiment_prefix=name)

import json

ROUTER_PROMPT = """Pick the best model for this request. Reply with JSON only:
{"model": "sarvam-105b" or "apodex", "confidence": 0 to 1}
sarvam-105b: reasoning, coding, architecture
apodex: research and comparing approaches
Request: """

def mercury_route(prompt):
    reply = call_decider(ROUTER_PROMPT + prompt)  # the decider model
    return json.loads(reply)                      # e.g. {"model": "sarvam-105b", "confidence": 0.9}

def generate_with_route(route, prompt):
    models = {"sarvam-105b": call_sarvam, "apodex": call_openrouter}
    try:
        return models[route["model"]](prompt)  # send the ORIGINAL prompt
    except Exception:
        return call_sarvam(prompt)              # fallback if the chosen model fails

